1	package service_test
2	
3	import (
4		"encoding/json"
5		"io"
6		"net/http"
7		"path/filepath"
8		"testing"
9		"time"
10	)
11	
12	// A parked long poll must be canceled when the service shuts down: SIGTERM
13	// interrupts the wait, the parked request answers a JSON 503, and the process
14	// exits zero promptly instead of holding the graceful drain until the waitMs
15	// deadline. No change or cursor is written by the canceled wait.
16	func TestProcessShutdownInterruptsLongPoll(t *testing.T) {
17		dataPath := filepath.Join(t.TempDir(), "sync.db")
18		p := startProcess(t, "SYNC_ADDR=127.0.0.1:0", "SYNC_DATA="+dataPath)
19	
20		// Seed one change so the document is known and a poll after cursor 1 parks.
21		if status, body := processJSON(t, http.MethodPost, "http://"+p.addr+"/v1/documents/doc/changes",
22			map[string]any{
23				"deviceId": "dev",
24				"changes":  []any{map[string]any{"id": "c1", "payload": map[string]any{"n": 1}}},
25			}); status != http.StatusOK || body["results"] == nil {
26			t.Fatalf("seed change: %d %v", status, body)
27		}
28	
29		type pollResult struct {
30			status int
31			body   map[string]any
32			err    error
33		}
34		result := make(chan pollResult, 1)
35		req, err := http.NewRequest(http.MethodGet,
36			"http://"+p.addr+"/v1/documents/doc/changes/poll?after=1&waitMs=30000", nil)
37		if err != nil {
38			t.Fatal(err)
39		}
40		go func() {
41			resp, err := http.DefaultClient.Do(req)
42			if err != nil {
43				result <- pollResult{err: err}
44				return
45			}
46			defer resp.Body.Close()
47			raw, _ := io.ReadAll(resp.Body)
48			var body map[string]any
49			_ = json.Unmarshal(raw, &body)
50			result <- pollResult{status: resp.StatusCode, body: body}
51		}()
52	
53		// Let the poll park before signaling shutdown.
54		time.Sleep(200 * time.Millisecond)
55	
56		terminated := make(chan int, 1)
57		go func() { terminated <- p.terminate(t) }()
58	
59		select {
60		case code := <-terminated:
61			if code != 0 {
62				t.Fatalf("exit code = %d, want 0", code)
63			}
64		case <-time.After(5 * time.Second):
65			_ = p.cmd.Process.Kill()
66			t.Fatal("shutdown waited for the long poll instead of interrupting it")
67		}
68	
69		select {
70		case r := <-result:
71			if r.err != nil {
72				// A hard connection drop is also a cancellation outcome, but the
73				// implemented contract answers 503 before draining, so require it.
74				t.Fatalf("poll connection error = %v, want 503 response", r.err)
75			}
76			if r.status != http.StatusServiceUnavailable {
77				t.Fatalf("poll status on shutdown = %d, want 503, body = %v", r.status, r.body)
78			}
79			if r.body["error"] == nil {
80				t.Fatalf("poll body = %v, want JSON error", r.body)
81			}
82		case <-time.After(2 * time.Second):
83			t.Fatal("parked poll did not return after shutdown")
84		}
85	}
