349			{"missing deviceId", "application/json", `{"operations":[{"id":"a","payload":1}]}`},
350			{"empty deviceId", "application/json", `{"deviceId":"","operations":[{"id":"a","payload":1}]}`},
351			{"missing operations", "application/json", `{"deviceId":"dev"}`},
352			{"empty operations", "application/json", `{"deviceId":"dev","operations":[]}`},
353			{"missing op id", "application/json", `{"deviceId":"dev","operations":[{"payload":1}]}`},
354			{"empty op id", "application/json", `{"deviceId":"dev","operations":[{"id":"","payload":1}]}`},
355			{"numeric op id", "application/json", `{"deviceId":"dev","operations":[{"id":1,"payload":1}]}`},
356			{"missing payload", "application/json", `{"deviceId":"dev","operations":[{"id":"a"}]}`},
