366				h.ServeHTTP(w, r)
367				if w.Code != http.StatusBadRequest {
368					t.Fatalf("status = %d, want 400, body = %s", w.Code, w.Body.String())
369				}
370				var b map[string]string
371				if err := json.Unmarshal(w.Body.Bytes(), &b); err != nil || b["error"] == "" {
372					t.Fatalf("body = %q", w.Body.String())
373				}
