470	func TestReplayConcurrentWithPosts(t *testing.T) {
471		h, _ := newTestHandler(t)
472		// Devices used by every goroutine must be registered first.
473		register := func(id string) {
474			w, _ := postJSON(t, h, "/v1/devices", map[string]string{"deviceId": id})
475			if w.Code != 200 {
