519			t.Fatalf("stored %d changes, want %d", got, 2*n)
520		}
521		if body["nextCursor"].(float64) != float64(2*n) {
522			t.Fatalf("nextCursor = %v, want %d", body["nextCursor"], 2*n)
523		}
524	}
