534		w, _ := postJSON(t, h, "/v1/devices", map[string]string{"deviceId": "dev"})
535		if w.Code != 200 {
536			t.Fatal(w.Body.String())
537		}
538		w, _ = postJSON(t, h, "/v1/documents/doc/replay", map[string]any{
539			"deviceId":   "dev",
540			"operations": []any{map[string]any{"id": "o1", "payload": map[string]any{"v": 1}}},
541		})
