	// compact line, item keys ordered id,deviceId,payload,cursor, exactly one
	// trailing newline.
	w, _ := doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?from=0")
	if w.Code != http.StatusOK {
