	w, _ = doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?from=3")
	if got := strings.TrimSpace(w.Body.String()); got != `{"changes":[{"id":"c3","deviceId":"dev","payload":{"n":3},"cursor":3}],"count":1}` {
		t.Fatalf("from-only body = %q", got)
