	w, _ = doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?to=1")
	if got := strings.TrimSpace(w.Body.String()); got != `{"changes":[{"id":"c1","deviceId":"dev","payload":{"n":1},"cursor":1}],"count":1}` {
		t.Fatalf("to-only body = %q", got)
	}

