	rows, next, err := s.ListChanges("doc", 0, 100)
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 3 || next != 3 {
		t.Fatalf("log = %+v next=%d, want 3 contiguous rows", rows, next)
	}
}

func TestReplayUnknownDeviceAndRevoked(t *testing.T) {
	s, _ := app.Open("")
