	revoked := []events.Change{{ID: "r1", DeviceID: "dev", Payload: json.RawMessage(`{"n":1}`)}}
	if _, err := s.ReplayChanges("doc", revoked); !errors.Is(err, store.ErrPermissionDenied) {
